const base = process.env.FIADOCHECK_API_URL || 'http://host.docker.internal:3000/api';
const webhook = $('Webhook Chat').first().json.body;
const token = webhook.authToken;
const idTendero = webhook.id_tendero ?? webhook.metadata?.id_tendero;

if (!token) {
  return JSON.stringify({ error: 'authToken requerido: el backend filtra por tendero vía JWT' });
}

const clienteId = $input.clienteId?.trim();
const query = $input.query?.trim();

const headers = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };

async function fetchJson(url) {
  const res = await fetch(url, { headers });
  const data = await res.json().catch(() => ({}));
  return { status: res.status, data };
}

if (clienteId) {
  const [detalle, historial, creditos] = await Promise.all([
    fetchJson(`${base}/clientes/${encodeURIComponent(clienteId)}`),
    fetchJson(`${base}/clientes/${encodeURIComponent(clienteId)}/historial`),
    fetchJson(`${base}/creditos/cliente/${encodeURIComponent(clienteId)}`),
  ]);
  return JSON.stringify({ id_tendero: idTendero, detalle: detalle.data, historial: historial.data, creditos_activos: creditos.data });
}

if (query) {
  const busqueda = await fetchJson(`${base}/clientes?q=${encodeURIComponent(query)}`);
  return JSON.stringify({ id_tendero: idTendero, resultados: busqueda.data });
}

return JSON.stringify({ error: 'Debes proporcionar clienteId o query' });

const webhook = $('Webhook Chat').first().json.body;
const agentOut = $input.first().json;

const raw = agentOut.output ?? agentOut.text ?? '';

// Extrae ACTION:<tool> si el agente lo incluyó
const actionMatch = raw.match(/ACTION:([a-z_]+)/i);
const action_executed = actionMatch ? actionMatch[1].toLowerCase() : null;

// Limpia la línea ACTION del texto visible
const respuesta = raw.replace(/\n?ACTION:[a-z_]+/gi, '').trim();

const sugerenciasPorAccion = {
  buscar_cliente: ['Registrar un pago', 'Agregar crédito', 'Ver mora'],
  agregar_credito: ['Consultar saldo', 'Registrar pago'],
  agregar_pago: ['Ver historial', '¿Quién me debe más?'],
  agregar_cliente: ['Agregar crédito', 'Buscar cliente'],
};

return [{
  json: {
    respuesta,
    mensaje: respuesta,
    action_executed,
    sessionId: webhook.sessionId,
    sugerencias: action_executed
      ? (sugerenciasPorAccion[action_executed] ?? [])
      : ['¿Quién me debe más?', 'Resumen del día', 'Créditos vencidos'],
    success: true,
  },
}];
